SELECT b.version, COUNT(CASE WHEN r.status = 'passed' THEN 1 ELSE 0 END) AS passed, COUNT(CASE WHEN r.status = 'failed' THEN 1 ELSE 0 END) AS failed, COUNT(CASE WHEN r.status = 'skipped' THEN 1 ELSE 0 END) AS skipped, ROUND(100.0 * COUNT(*) FILTER (WHERE r.status = 'passed') / (COUNT(*) FILTER (WHERE r.status = 'passed') + COUNT(*) FILTER (WHERE r.status = 'failed')), 1) AS pass_rate FROM builds b JOIN test_runs tr ON tr.build_id = b.build_id JOIN test_results r ON r.test_run_id = tr.test_run_id GROUP BY b.build_id, b.version HAVING COUNT(*) FILTER (WHERE r.status = 'failed') > 0;
